// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    Reverter r;
    address payable recv;

    function setUp() public { c = new MyContract(); r = new Reverter(); recv = payable(address(r)); }

    function testFuzz_property(uint256 amount, bool wantFail) public {
        amount = bound(amount, 1, type(uint256).max / 2);
        vm.deal(address(c), amount);

        address payable target = wantFail ? recv : payable(address(new Acceptor()));
        uint256 balBefore = address(c).balance;

        bool ok;
        try c.sendTo(target, amount) { ok = true; } catch { ok = false; }

        // Rule: if sendTo reported success, exactly `amount` wei left c.
        assertTrue(!ok || address(c).balance == balBefore - amount);
    }
}

contract Reverter {
    fallback() external payable { revert(); }
}

contract Acceptor {
    fallback() external payable {}
}
